-- Module 6 (AI Agents & Tools) content enrichment: adds visual diagrams,
-- in-lesson practice checks, worked code examples, and (lesson 34) an
-- interactive code_practice. Additive only (jsonb ||), existing hook/
-- explanation/analogy/fun_fact/try_it fields are untouched.
--
-- This module maps most directly onto the Hugging Face Agents Course and
-- Stanford CS329Z: lesson 34 uses a real function-calling tool schema, lesson
-- 35 runs an actual printed Thought/Action/Observation (ReAct) trace, and
-- lesson 36 shows real plan-then-execute-then-replan logic, instead of staying
-- at pure description of these patterns.

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# A CHATBOT just replies with text\ndef chatbot_reply(user_message):\n    return \"The weather today is sunny, 28C.\"  # made up, static, never actually checked\n\n# An AGENT can actually DO something -- call a real function, use a real result\ndef get_real_weather(city):\n    # in real life this would call a weather API\n    weather_data = {\"Accra\": \"Rainy, 26C\", \"Kumasi\": \"Sunny, 30C\"}\n    return weather_data.get(city, \"Unknown city\")\n\ndef agent_reply(user_message, city):\n    # the agent decides it needs to call a tool, then uses the REAL result\n    result = get_real_weather(city)\n    return f\"I checked live data -- it''s currently {result} in {city}.\"\n\nprint(chatbot_reply(\"What''s the weather in Accra?\"))\nprint(agent_reply(\"What''s the weather in Accra?\", \"Accra\"))","visual":{"caption":"Same conversation, very different capability underneath","steps":[{"emoji":"💬","label":"Chatbot","caption":"Text in, text out — everything comes from what it already knows."},{"emoji":"🤖","label":"Agent: Decide","caption":"Does answering this actually require doing something?"},{"emoji":"🛠️","label":"Agent: Act","caption":"Calls a real tool — a search, a calculation, an API."},{"emoji":"👀","label":"Agent: Observe","caption":"Reads back the real result of that action."},{"emoji":"💬","label":"Agent: Respond","caption":"Answers using what it actually just found out, not a guess."}]},"practice":{"prompt":"A bot is asked \"What is 847 × 293?\" A pure chatbot guesses from patterns in its training text. What would an agent do differently?","options":["Call an actual calculator tool and use the real computed result","Nothing — chatbots and agents always behave identically","Refuse to answer any math question","Ask a human to do the multiplication instead"],"correct_index":0,"feedback":"That is the entire distinction: a chatbot predicts a plausible-sounding answer, while an agent can reach for a tool that actually computes the correct one."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 33;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# This is close to the real JSON format models like GPT/Claude use to\n# understand what a tool does and what inputs it needs\ncalculator_tool = {\n    \"name\": \"calculator\",\n    \"description\": \"Evaluates a basic math expression. Use for exact arithmetic.\",\n    \"parameters\": {\"expression\": \"string, e.g. ''12 * (3 + 4)''\"},\n}\n\nsearch_tool = {\n    \"name\": \"web_search\",\n    \"description\": \"Searches the web for current information the model was not trained on.\",\n    \"parameters\": {\"query\": \"string, the search terms\"},\n}\n\ndef calculator(expression):\n    # simplified for teaching -- a real system would use a safe math parser,\n    # never raw eval() on text that came from a model or a user\n    return eval(expression)\n\n# The model reads the description, decides \"calculator\" fits, picks the input\npicked_tool = calculator_tool[\"name\"]\npicked_input = \"12 * (3 + 4)\"\nprint(f\"Model picked: {picked_tool}({picked_input})\")\nprint(f\"Result: {calculator(picked_input)}\")","visual":{"caption":"What a model actually reads to decide which tool to use","steps":[{"emoji":"🏷️","label":"Name","caption":"A short, unambiguous identifier for the tool."},{"emoji":"📝","label":"Description","caption":"Plain language: what it does, and when to use it."},{"emoji":"📥","label":"Required Inputs","caption":"Exactly what information the tool needs to run."},{"emoji":"🧠","label":"Model Decides","caption":"Reads every available tool description, picks the best fit."},{"emoji":"▶️","label":"Executes","caption":"Your code runs the real function and returns the result."}]},"practice":{"prompt":"A tool is described only as \"calculator\" with no further detail, alongside five other vaguely-named tools. What usually happens?","options":["The model picks the wrong tool more often, since it has too little information to judge fit","The model always picks correctly regardless of description quality","Vague descriptions make the tool run faster","Tools do not need descriptions at all"],"correct_index":0,"feedback":"The description IS the interface — a vague one gets used at the wrong moments, exactly the way a vague variable name confuses a human reading code."},"code_practice":{"instructions":"This tool definition is missing its description entirely. Add one that says what the tool does and when a model should use it — the model literally cannot pick this tool correctly without it.","starter":"get_time_tool = {\n    \"name\": \"get_current_time\",\n    # TODO: add a \"description\" key here explaining what this tool does\n    \"parameters\": {\"timezone\": \"string, e.g. ''GMT''\"},\n}\n\nprint(get_time_tool)","check_pattern":"\"description\"\\s*:","success_message":"Now a model reading this tool has enough to decide, correctly, when \"get_current_time\" is the right pick.","hint":"Add a line like: \"description\": \"Returns the current time for a given timezone. Use when the user asks what time it is.\""}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 34;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# A simplified trace of the ReAct loop: Thought -> Action -> Observation\ndef get_capital(country):\n    capitals = {\"Ghana\": \"Accra\", \"Kenya\": \"Nairobi\", \"France\": \"Paris\"}\n    return capitals.get(country, \"Unknown\")\n\ndef calculator(expr):\n    return eval(expr)  # simplified for teaching, see the tools lesson for the caveat\n\nquestion = \"What is Ghana''s capital''s approximate population, doubled?\"\n\ntrace = []\ntrace.append((\"Thought\", \"I need to find Ghana''s capital first.\"))\ntrace.append((\"Action\", \"get_capital(''Ghana'')\"))\nobservation = get_capital(\"Ghana\")\ntrace.append((\"Observation\", observation))\n\ntrace.append((\"Thought\", f\"The capital is {observation}. Now I need its population, doubled.\"))\ntrace.append((\"Action\", \"calculator(''2745000 * 2'')\"))\nobservation2 = calculator(\"2745000 * 2\")\ntrace.append((\"Observation\", observation2))\n\ntrace.append((\"Thought\", \"I now have enough information to answer.\"))\ntrace.append((\"Action\", \"Final Answer\"))\n\nfor step, value in trace:\n    print(f\"{step}: {value}\")","visual":{"caption":"The three-word loop that turns a text predictor into something that gets things done","steps":[{"emoji":"💭","label":"Thought","caption":"The model reasons out loud about what to do next."},{"emoji":"⚡","label":"Action","caption":"It picks one tool and the exact input to give it."},{"emoji":"👀","label":"Observation","caption":"Your code runs the tool and returns the real result."},{"emoji":"🔁","label":"Loop or Answer","caption":"Repeat with the new information, or finish once ready."}]},"practice":{"prompt":"Why is it useful that Thought, Action, and Observation are all VISIBLE, not hidden inside the model?","options":["You can see exactly where an agent went wrong — a bad thought, a wrong tool pick, or a broken tool","It makes the agent run faster","It has no practical benefit, it is just for show","It prevents the agent from ever making mistakes"],"correct_index":0,"feedback":"This is the debugging window for agents: a bad Thought means unclear instructions, a bad Action means the wrong tool was chosen, and a bad Observation means the tool itself failed."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 35;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"goal = \"Plan a birthday surprise party\"\n\n# A multi-step agent breaks a big goal into an ordered plan FIRST,\n# then executes each step -- adjusting if a step reveals new information\nplan = [\n    \"Check the guest list and confirm availability\",\n    \"Pick a date that works for the most people\",\n    \"Book a venue for that date\",\n    \"Order a cake\",\n    \"Send invitations\",\n]\n\nfor i, step in enumerate(plan, start=1):\n    print(f\"Step {i}: {step}\")\n\ndef execute_step(step):\n    if \"Book a venue\" in step:\n        return \"FAILED: venue unavailable on that date\"\n    return \"done\"\n\nprint()\nfor step in plan:\n    result = execute_step(step)\n    if \"FAILED\" in result:\n        print(f\"''{step}'' failed -> replanning: picking a new date and retrying\")\n        break\n    print(f\"''{step}'' -> {result}\")","visual":{"caption":"Planning ahead instead of reacting one step at a time","steps":[{"emoji":"🎯","label":"Big Goal","caption":"A task too large to solve in a single tool call."},{"emoji":"📋","label":"Break Into Steps","caption":"An ordered plan, decided before execution begins."},{"emoji":"▶️","label":"Execute a Step","caption":"Run one step, using the tools available."},{"emoji":"🔍","label":"Check the Result","caption":"Did it actually work, or did something fail?"},{"emoji":"🔄","label":"Adjust If Needed","caption":"A failed step triggers replanning, not giving up."}]},"practice":{"prompt":"In the code above, what happens when \"Book a venue\" fails?","options":["The agent stops executing the old plan and replans instead of blindly continuing","The program crashes with no recovery","It skips straight to sending invitations for a party with no venue","Nothing — the failure is silently ignored"],"correct_index":0,"feedback":"Good multi-step agents treat a failed step as new information that should change the plan, not as a reason to either crash or barrel ahead as if nothing happened."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 36;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# SHORT-TERM MEMORY: just the current conversation, lost when it ends\nconversation_history = []\n\ndef chat(user_message, history):\n    history.append({\"role\": \"user\", \"content\": user_message})\n    reply = f\"Got it, you said: ''{user_message}''\"\n    history.append({\"role\": \"assistant\", \"content\": reply})\n    return reply\n\nchat(\"My name is Ama\", conversation_history)\nchat(\"What''s my name?\", conversation_history)\nprint(conversation_history)\n\n# LONG-TERM MEMORY: facts saved somewhere that persists ACROSS sessions\nlong_term_memory = {}\n\ndef remember_fact(key, value):\n    long_term_memory[key] = value\n\ndef recall_fact(key):\n    return long_term_memory.get(key, \"I don''t know that yet\")\n\nremember_fact(\"user_name\", \"Ama\")\nprint(recall_fact(\"user_name\"))   # still works even in a brand-new conversation","visual":{"caption":"Two very different kinds of \"remembering\"","steps":[{"emoji":"💬","label":"Short-Term Memory","caption":"The current conversation only — gone the moment it ends."},{"emoji":"🗄️","label":"Long-Term Memory","caption":"Facts saved somewhere durable, available in future sessions too."},{"emoji":"🧹","label":"Forgetting","caption":"What silently drops out once the context window fills up."}]},"practice":{"prompt":"A user tells a bot their favorite color today. Tomorrow, in a brand-new conversation, the bot still remembers it. What made that possible?","options":["The fact was written to long-term (persisted) memory, not just kept in that one conversation","It''s impossible — bots can never remember anything across sessions","The context window automatically saves everything forever","The user must have typed it again"],"correct_index":0,"feedback":"Short-term memory dies with the conversation. Anything that needs to survive to a NEW conversation has to be explicitly written somewhere durable — that''s long-term memory."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 37;

